+    if (BIO_printf(out, "%*sAlgorithm: ", indent, "") <= 0)
+        return 0;
+    if (i2a_ASN1_OBJECT(out, hash->algorithmIdentifier->algorithm) <= 0)
+        return 0;
+    if (BIO_puts(out, "\n") <= 0)
+        return 0;
