+        return 0;
+    if (BIO_printf(out, "%*sPrivilege Policy Syntax:\n", indent, "") <= 0)
+        return 0;
+    return i2r_OSSL_INFO_SYNTAX(method, ppid->privPolSyntax, out, indent + 4);
